INSERT INTO `reseller_policies` (`id`, `title`, `summary`, `points`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES
('5c67a413-50d1-414a-9199-592c52a79022', 'ডেলিভারি চার্জ', 'প্রতিটি অর্ডারে ডেলিভারি চার্জ কীভাবে নির্ধারণ হয়।', '[\"ডিফল্ট ডেলিভারি রুল: সাধারণ ডেলিভারি চার্জ এলাকা অনুযায়ী (Inside Dhaka / Sub Dhaka / Outside Dhaka) নির্ধারিত হবে।\",\"বিশেষ প্রোডাক্ট বা অফার: কিছু প্রোডাক্টে নির্দিষ্ট ডেলিভারি চার্জ বা ফ্রি-শিপিং প্রযোজ্য হতে পারে। অ্যাডমিন ফ্রি-শিপিং দিলে কোনো ডেলিভারি চার্জ লাগবে না।\",\"ফ্লেক্সিবল ডেলিভারি চার্জ: রিসেলার চাইলে প্রফিট মার্জিন হিসাব করে কাস্টমার থেকে ডেলিভারি চার্জ কম-বেশি বা ফ্রি করতে পারেন।\",\"হিসাবের নিয়ম: সিস্টেম থেকে শুধু নির্ধারিত চার্জটিই (যেমন: ৬০ টাকা) কাটা হবে। কাস্টমারের থেকে বেশি চার্জ নিলে (যেমন: ১০০ টাকা) বাড়তি ৪০ টাকা রিসেলারের অতিরিক্ত প্রফিট হবে; আবার ডেলিভারি ফ্রি দিলে সেই অনুযায়ী প্রফিট কমবে।\",\"চার্জ পরিবর্তন: বিশেষ প্রয়োজনে অ্যাডমিন ডেলিভারি চার্জ পরিবর্তন করতে পারেন, যা প্রোডাক্ট নোটে জানিয়ে দেওয়া হবে।\"]', 1, 1, '2026-09-01 07:34:19.713738+00', '2026-09-01 08:09:41.232+00'),
('2c0c2ef2-0ef3-449c-ab7c-ddbaf8cc2eae', 'ডেলিভারি ব্যর্থ বা রিটার্ন', 'পার্সেল ফিরে এলে কী হয়।', '[\"পার্সেল সম্পূর্ণ রিটার্ন হলে কাস্টমারের কাছ থেকে কোনো টাকা পাওয়া যায় না।\",\"তবুও সেই অর্ডারের ডেলিভারি (রিটার্ন) চার্জ ও প্যাকেজিং খরচ আপনাকে বহন করতে হবে।\",\"অর্থাৎ রিটার্ন অর্ডারে লোকসান = ডেলিভারি + প্যাকেজিং।\",\"বারবার ফেক বা উদাসীন অর্ডার হলে অ্যাকাউন্টে সীমাবদ্ধতা আসতে পারে।\"]', 3, 1, '2026-09-01 07:34:19.713738+00', '2026-09-01 08:18:02.516+00'),
('adad5568-1191-4188-9ae2-cdc25c672797', 'আংশিক ডেলিভারি', 'কাস্টমার অর্ডারের অংশ রাখলে যা হয়।', '[\"অ্যাডমিন কাস্টমারের কাছ থেকে প্রাপ্ত প্রকৃত টাকার পরিমাণ রেকর্ড করেন।\",\"ফুল-আইটেম পারশাল: কাস্টমার সব প্রোডাক্ট রাখে কিন্তু কম বা বেশি টাকা দেয়; পুরো খরচ প্রযোজ্য থাকে।\",\"আইটেম পারশাল: শুধু রাখা প্রোডাক্টের টাকা ধরা হয়; ফেরত প্রোডাক্ট স্টকে ফিরে যায়।\",\"ডেলিভারি-অনলি পারশাল: কাস্টমার শুধু ডেলিভারি চার্জ দেয় এবং সব প্রোডাক্ট ফেরত দেয়।\",\"প্রতিটি পারশালে প্রফিট = প্রাপ্ত টাকা - প্রযোজ্য খরচ।\"]', 4, 1, '2026-09-01 07:34:19.713738+00', '2026-09-01 07:34:19.713738+00'),
('2438c245-0b09-4449-b613-af2b42014a9a', 'অর্ডার ফ্লো ও স্ট্যাটাস', 'কে কী পরিবর্তন করতে পারবেন এবং কখন।', '[\"অর্ডার Pending থাকা অবস্থায় আপনি তৈরি, এডিট, ডিলিট ও স্ট্যাটাস পরিবর্তন করতে পারবেন।\",\"Send to admin করার পর অর্ডারটি আপনার জন্য লক হয়ে যায় এবং অ্যাডমিন যাচাই শুরু হয়।\",\"অ্যাডমিন অর্ডারটি Confirmed, Packaging, Ready to ship ও Courier booking ধাপে এগিয়ে নেন।\",\"কুরিয়ার ওয়েবহুক Delivered, Partial ও Return স্ট্যাটাস স্বয়ংক্রিয়ভাবে আপডেট করে।\",\"চূড়ান্ত সেটেলমেন্ট (রিটার্ন রিসিভ, পারশাল টাইপ, ড্যামেজড) শুধু অ্যাডমিন করেন।\"]', 5, 1, '2026-09-01 07:34:19.713738+00', '2026-09-01 07:34:19.713738+00'),
('a0b8fcb2-f0a0-4251-aa17-b346f42d261c', 'ড্যামেজড বা হারানো প্রোডাক্ট', 'প্রোডাক্ট ড্যামেজ হয়ে ফিরে এলে যা হয়।', '[\"ডেলিভারি, রিটার্ন বা পারশাল সেটেলমেন্টের পর অর্ডারটি Damaged চিহ্নিত করা যায়।\",\"কাস্টমারের কাছ থেকে যা সংগ্রহ হয়েছে তা প্রাপ্ত হিসেবে ধরা হয়।\",\"এই ক্ষেত্রে রিসেলার কে প্রোডাক্ট এর কোনো ক্ষতি পূরণ দিতে হবে না।\"]', 6, 1, '2026-09-01 07:34:19.713738+00', '2026-09-01 08:20:46.813+00'),
('cbe66ac6-ce1f-4e9b-a724-4a788f875192', 'পেমেন্ট, ব্যালেন্স ও পেআউট', 'আপনার টাকা কীভাবে আসে-যায়।', '[\"অর্ডার সেটেল হওয়ার পরই প্রফিট আপনার ব্যালেন্সে যোগ হয়।\",\"রিটার্ন  অর্ডারের লোকসান একই ব্যালেন্স থেকে কাটা হয়।\",\"পেআউট রিকোয়েস্ট অ্যাডমিন রিভিউ করে আপনার সংরক্ষিত পেআউট মেথডে পেমেন্ট করা হয়।\",\"ফ্রোজন বা রিকোয়ার্ড ডিপোজিট অংশ উত্তোলনযোগ্য নয়।\",\"প্রতিটি ক্রেডিট ও ডেবিট Transactions রিপোর্টে দেখা যায়।\"]', 7, 1, '2026-09-01 07:34:19.713738+00', '2026-09-01 08:21:26.264+00'),
('82d5dc20-c8ef-475c-aae7-d23952967e56', 'সাবস্ক্রিপশন ও অ্যাক্সেস', 'প্ল্যান, ট্রায়াল ও গ্রেস পিরিয়ডের নিয়ম।', '[\"প্যানেল (এবং অন্তর্ভুক্ত থাকলে স্টোরফ্রন্ট) চালু রাখতে একটি প্ল্যান প্রয়োজন।\",\"সাবস্ক্রিপশন ফি আপনার আর্নিং থেকে কাটা যায় অথবা উপলভ্য পেমেন্ট মেথডে পরিশোধ করা যায়।\",\"ট্রায়াল পিরিয়ডে কোনো খরচ ছাড়াই পূর্ণ অ্যাক্সেস পাবেন।\",\"মেয়াদ শেষ হলে গ্রেস পিরিয়ড প্রযোজ্য হয়; গ্রেস শেষে অ্যাক্সেস সীমিত হয়ে যায়।\"]', 8, 1, '2026-09-01 07:34:19.713738+00', '2026-09-01 08:21:52.986+00'),
('9a5b2ad6-b189-4caa-9022-e7c3c03a7b12', 'প্রফিট হিসাব', 'একটি অর্ডারে আপনার প্রফিট কীভাবে হিসাব হয়।', '[\"প্রফিট = কাস্টমারের কাছ থেকে প্রাপ্ত টাকা - প্রোডাক্ট খরচ - ডেলিভারি খরচ - প্যাকেজিং খরচ।\",\"উদাহরণঃ ১০০০-৫০০-১০০-২০=৩৮০ টাকা প্রফিট\",\"প্রোডাক্ট খরচ হলো কাস্টমার যে প্রোডাক্টগুলো রেখেছে সেগুলোর অ্যাডমিন (রিসেলার) প্রাইস।\",\"প্যাকেজিং খরচ প্রোডাক্ট সেটিংস থেকে আসে এবং প্রতি অর্ডারে যোগ হয়।\",\"আপনি যে ডিস্কাউন্ট দেন তা আপনার নিজের প্রফিট থেকে কাটা হয়, অ্যাডমিন প্রাইস থেকে নয়।\",\"অর্ডার সেটেল (delivered / partial / returned) না হওয়া পর্যন্ত প্রফিট চূড়ান্ত হয় না।\"]', 2, 1, '2026-09-01 07:34:19.713738+00', '2026-09-01 08:17:23.325+00'),
('3d1b78f8-b305-4b4a-91fc-c7310ace780a', 'প্রোডাক্ট, প্রাইস ও স্টক', 'আপনার স্টোরের ক্যাটালগ নিয়ম।', '[\"বিক্রয় মূল্য আপনি নিজে ঠিক করবেন, তবে তা অ্যাডমিন প্রাইসের নিচে হতে পারবে না।\",\"লাইভ স্টক অনুযায়ী অর্ডার গৃহীত হয়; স্টক শেষ হলে প্রোডাক্ট স্টোর থেকে স্বয়ংক্রিয়ভাবে হাইড হয়।\",\"আপনার স্টোরে লিস্ট করা না থাকলেও যেকোনো অ্যাক্টিভ ক্যাটালগ প্রোডাক্টের অর্ডার তৈরি করতে পারবেন।\",\"প্রোডাক্টের ছবি ও বিবরণ শুধুমাত্র নিজের স্টোরের মার্কেটিংয়ে ব্যবহার করা যাবে।\"]', 9, 1, '2026-09-01 07:34:19.713738+00', '2026-09-01 08:22:29.597+00'),
('87e45039-3afa-4854-a038-ba89ce341630', 'অ্যাকাউন্ট ও নিরাপত্তা', 'আপনার অ্যাকাউন্ট নিরাপদ রাখার নিয়ম।', '[\"লগইন তথ্য গোপন রাখুন; আপনার অ্যাকাউন্টে হওয়া সব কাজের দায়িত্ব আপনার।\",\"ভুল বা ভুয়া তথ্য দিলে অ্যাকাউন্ট স্থগিত হতে পারে।\",\"প্ল্যাটফর্মের নিয়ম লঙ্ঘন করলে নোটিশ ছাড়াই অ্যাক্সেস বন্ধ হতে পারে।\",\"যেকোনো সমস্যায় সাপোর্টের সাথে যোগাযোগ করুন।\"]', 10, 1, '2026-09-01 07:34:19.713738+00', '2026-09-01 08:22:48.804+00');
